package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of truth for an owner's {@code identityKey}: the one derived value that all
 * create-time duplicate detection for {@code POST /owners} is expressed through. It consolidates
 * what used to be three separate guards (telephone, email and household) into a single key, so a
 * request is a duplicate only when its <em>whole</em> key equals an existing owner's.
 *
 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or
 * empty)}:
 * <ul>
 *   <li>telephone is canonicalised to E.164 ({@link OwnerTelephone#toE164(String)}) so the
 *       comparison is independent of how a value happens to be formatted;</li>
 *   <li>email is the stored lower-cased form ({@link OwnerEmail#normalize(String)}) when present,
 *       otherwise the empty string (email is optional);</li>
 *   <li>householdId is the owner's shared-household identifier when it carries one, otherwise the
 *       empty string.</li>
 * </ul>
 *
 * <p>Because the telephone is part of the key, two members of the same household (same
 * {@code householdId}) with different telephones have different keys and are both allowed; only an
 * exact full-key match counts as a duplicate.
 *
 * <p>Centralised here so {@link CheckOwnerIdentityUnique} (which rejects collisions) and the owner
 * mapper (which returns the key) cannot disagree on how it is derived.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /** The identity key of an existing owner, derived from its stored fields. */
    public static String of(Owner owner) {
        return key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    /**
     * The identity key for the given parts: {@code normalizedTelephone + '|' + (email or empty) +
     * '|' + (householdId or empty)}.
     */
    public static String key(String telephone, String email, String householdId) {
        return OwnerTelephone.toE164OrRaw(telephone) + "|" + normalizeEmail(email) + "|"
                + (householdId == null ? "" : householdId);
    }

    private static String normalizeEmail(String email) {
        return OwnerEmail.isPresent(email) ? OwnerEmail.normalize(email) : "";
    }
}
===== rest/function/owner/CheckOwnerIdentityUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Create-time uniqueness guard for {@code POST /owners}: the single duplicate check. It rejects a
 * request whose whole {@link OwnerIdentity identityKey} equals an existing owner's, with a 409 via
 * {@link DuplicateIdentityException}. This one key subsumes the former separate telephone, email
 * and household guards: a collision requires the normalised telephone, the email and the household
 * to all match, so (for example) two members of one household with different telephones are both
 * allowed.
 *
 * <p>Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail} so the request's
 * telephone and email are already in their stored (canonical) forms, and before {@link BuildOwner}.
 * A new owner's {@code householdId} is not assigned until later in the pipeline, so the request's
 * household component is empty here; it is compared against each existing owner's stored key.
 */
public class CheckOwnerIdentityUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), null);
        for (Owner existing : ownerRepository.findAll()) {
            if (identityKey.equals(OwnerIdentity.of(existing))) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}
===== rest/function/owner/DuplicateIdentityException =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link CheckOwnerIdentityUnique} when an owner create request's whole
 * {@link OwnerIdentity identityKey} equals an existing owner's — i.e. the request matches on
 * normalised telephone, email and household together. Checked so it appears in the
 * {@code throws} clause and is routed to its escalation handler, which responds 409.
 */
public class DuplicateIdentityException extends Exception {

    public DuplicateIdentityException(String identityKey) {
        super("An owner with this identity already exists: " + identityKey);
    }
}
