===== AssignPossibleDuplicate =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Soft-duplicate detection for {@code POST /owners}. A request that cleared the hard-duplicate
 * guard ({@link CheckOwnerIdentityUnique}) is still created, but is flagged as a <em>possible</em>
 * duplicate when it shares an existing owner's {@code lastName} and {@code postcode} while carrying
 * a <em>different</em> telephone. The matching owner's id is recorded in {@code possibleDuplicateOf};
 * when there is no such match both {@code possibleDuplicate} is {@code false} and
 * {@code possibleDuplicateOf} is {@code null}.
 *
 * <p>Runs within the create transaction after {@link BuildOwner} (so the built owner's telephone is
 * already in its stored E.164 form) and before {@link SaveOwner} (so {@code findAll} excludes the
 * owner being created). When several existing owners match, the one with the lowest id is recorded
 * so the result is deterministic. A request without a postcode cannot share one, so it is never a
 * possible duplicate.
 */
public class AssignPossibleDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        owner.setPossibleDuplicate(false);
        owner.setPossibleDuplicateOf(null);

        String postcode = owner.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return;
        }
        String lastName = owner.getLastName();
        String telephone = owner.getTelephone();

        Owner match = null;
        for (Owner existing : ownerRepository.findAll()) {
            boolean sameLastName = lastName != null && lastName.equalsIgnoreCase(existing.getLastName());
            boolean samePostcode = postcode.equals(existing.getPostcode());
            boolean differentTelephone = telephone == null || !telephone.equals(existing.getTelephone());
            if (sameLastName && samePostcode && differentTelephone) {
                if (match == null || existing.getId() < match.getId()) {
                    match = existing;
                }
            }
        }
        if (match != null) {
            owner.setPossibleDuplicate(true);
            owner.setPossibleDuplicateOf(match.getId());
        }
    }
}
===== AssignNamesakeCount =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code namesakeCount}: the number of existing owners that share the new
 * owner's {@code firstName} and {@code lastName}, compared case-insensitively.
 *
 * <p>Runs within the create transaction after {@link BuildOwner} and before {@link SaveOwner},
 * so the count reflects the owners that already exist and excludes the owner being created.
 */
public class AssignNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (firstName.equalsIgnoreCase(existing.getFirstName())
                    && lastName.equalsIgnoreCase(existing.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }
}
===== OwnerAddress =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Single source of truth for the owner address normalisation rule used across the
 * {@code POST /owners} pipeline: an address is canonicalised by trimming, collapsing internal
 * whitespace to single spaces, upper-casing, and expanding common abbreviations as whole words
 * ({@code ST}→{@code STREET}, {@code RD}→{@code ROAD}, {@code AVE}→{@code AVENUE}). So
 * {@code "  12  main  st "} canonicalises to {@code "12 MAIN STREET"} and {@code "7 elm ave"} to
 * {@code "7 ELM AVENUE"}.
 *
 * <p>Centralised here (rather than inlined) so every site agrees on one definition:
 * {@link ValidateOwnerFields} stores the canonical value and rejects a value that is blank once
 * normalised, while {@link OwnerHousehold} compares the canonical value for duplicate detection
 * and the shared household id.
 */
final class OwnerAddress {

    /** Whole-word abbreviations expanded during normalisation. */
    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET",
            "RD", "ROAD",
            "AVE", "AVENUE");

    private OwnerAddress() {
    }

    /**
     * The stored/returned/compared form: trimmed, internal whitespace collapsed to single
     * spaces, upper-cased, with common abbreviations expanded as whole words. Returns an empty
     * string for a null or whitespace-only input.
     */
    static String normalize(String address) {
        if (address == null) {
            return "";
        }
        String trimmed = address.trim();
        if (trimmed.isEmpty()) {
            return "";
        }
        String[] tokens = trimmed.toUpperCase(Locale.ROOT).split("\\s+");
        StringBuilder sb = new StringBuilder();
        for (String token : tokens) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(token, token));
        }
        return sb.toString();
    }
}
===== BuildOwner =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        LocalDate effective = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
        // The effective registration date (supplied or defaulted) must fall on a business day;
        // a weekend rolls forward to Monday. Everything derived from it (e.g. the membership
        // number's year segment) then reads this adjusted value.
        owner.setRegistrationDate(BusinessDay.rollForward(effective));
        built.set(owner);
    }
}

